PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS api_keys(key_id TEXT PRIMARY KEY CHECK(length(key_id) BETWEEN 1 AND 64),salt TEXT NOT NULL CHECK(length(salt)=32 AND salt NOT GLOB '*[^0-9a-f]*'),digest BLOB NOT NULL CHECK(length(digest)=32),created_at INTEGER NOT NULL CHECK(created_at>0),disabled_at INTEGER CHECK(disabled_at IS NULL OR disabled_at>=created_at)) STRICT;
CREATE TABLE IF NOT EXISTS verification_batches(
 verification_id TEXT PRIMARY KEY CHECK(length(verification_id)=36 AND verification_id=lower(verification_id) AND substr(verification_id,9,1)='-' AND substr(verification_id,14,1)='-' AND substr(verification_id,19,1)='-' AND substr(verification_id,24,1)='-' AND replace(verification_id,'-','') NOT GLOB '*[^0-9a-f]*' AND substr(verification_id,15,1) GLOB '[1-5]' AND substr(verification_id,20,1) GLOB '[89ab]'),owner_key_id TEXT NOT NULL REFERENCES api_keys(key_id),
 merkle_root_hash TEXT NOT NULL UNIQUE CHECK(length(merkle_root_hash)=66 AND substr(merkle_root_hash,1,2)='0x' AND substr(merkle_root_hash,3) NOT GLOB '*[^0-9a-f]*'),leaf_hash TEXT NOT NULL CHECK(length(leaf_hash)=66 AND substr(leaf_hash,1,2)='0x' AND substr(leaf_hash,3) NOT GLOB '*[^0-9a-f]*'),leaf_index INTEGER NOT NULL CHECK(leaf_index>=0),session_id TEXT NOT NULL CHECK(length(CAST(session_id AS BLOB)) BETWEEN 1 AND 64),payload_digest TEXT NOT NULL CHECK(length(payload_digest)=66 AND substr(payload_digest,1,2)='0x' AND substr(payload_digest,3) NOT GLOB '*[^0-9a-f]*'),r2_key TEXT NOT NULL UNIQUE,
 status TEXT NOT NULL CHECK(status IN('stored','queued','processing','submitted','anchored','failed')),anchoring_mode TEXT NOT NULL CHECK(anchoring_mode IN('enabled','disabled')),verification_mode TEXT NOT NULL CHECK(verification_mode='commitment_only'),proof_type TEXT NOT NULL CHECK(proof_type='local_merkle_stub'),proof_version TEXT NOT NULL CHECK(proof_version='1.0.0'),envelope_version TEXT NOT NULL CHECK(envelope_version='1'),attestation INTEGER NOT NULL CHECK(attestation=0),chain TEXT NOT NULL CHECK(chain IN('base-sepolia','base-mainnet')),network TEXT NOT NULL CHECK(network IN('84532','8453')),attempts INTEGER NOT NULL DEFAULT 0 CHECK(attempts>=0),last_error TEXT,
 tx_hash TEXT UNIQUE CHECK(tx_hash IS NULL OR(length(tx_hash)=66 AND substr(tx_hash,1,2)='0x' AND substr(tx_hash,3) NOT GLOB '*[^0-9a-f]*')),tx_nonce INTEGER CHECK(tx_nonce IS NULL OR tx_nonce>=0),confirmations INTEGER NOT NULL DEFAULT 0 CHECK(confirmations>=0),required_confirmations INTEGER NOT NULL CHECK(required_confirmations BETWEEN 1 AND 100),finality_block INTEGER CHECK(finality_block IS NULL OR finality_block>=0),anchor_lease_token TEXT,anchor_lease_until INTEGER,
 created_at INTEGER NOT NULL CHECK(created_at>0),updated_at INTEGER NOT NULL,submitted_at INTEGER,anchored_at INTEGER,CHECK(updated_at>=created_at),CHECK((tx_hash IS NULL)=(tx_nonce IS NULL)),CHECK((anchor_lease_token IS NULL)=(anchor_lease_until IS NULL)),CHECK(submitted_at IS NULL OR submitted_at>=created_at),CHECK(anchored_at IS NULL OR(submitted_at IS NOT NULL AND anchored_at>=submitted_at)),CHECK(status!='stored' OR(anchoring_mode='disabled' AND attempts=0 AND tx_hash IS NULL AND anchor_lease_token IS NULL)),CHECK(status!='submitted' OR tx_hash IS NOT NULL),CHECK(status!='anchored' OR(tx_hash IS NOT NULL AND anchored_at IS NOT NULL AND confirmations>=required_confirmations))
) STRICT;
CREATE INDEX IF NOT EXISTS idx_batches_owner_id ON verification_batches(owner_key_id,verification_id);CREATE INDEX IF NOT EXISTS idx_batches_status_updated ON verification_batches(status,updated_at);CREATE INDEX IF NOT EXISTS idx_batches_lease ON verification_batches(anchor_lease_until) WHERE anchor_lease_until IS NOT NULL;CREATE INDEX IF NOT EXISTS idx_batches_tx_hash ON verification_batches(tx_hash) WHERE tx_hash IS NOT NULL;
CREATE TABLE IF NOT EXISTS proof_leaves(verification_id TEXT NOT NULL REFERENCES verification_batches(verification_id) ON DELETE CASCADE,leaf_index INTEGER NOT NULL CHECK(leaf_index>=0),leaf_hash TEXT NOT NULL CHECK(length(leaf_hash)=66 AND substr(leaf_hash,1,2)='0x' AND substr(leaf_hash,3) NOT GLOB '*[^0-9a-f]*'),target_domain TEXT NOT NULL CHECK(length(CAST(target_domain AS BLOB)) BETWEEN 1 AND 253 AND target_domain=lower(target_domain)),path TEXT NOT NULL CHECK(substr(path,1,1)='/' AND instr(path,'?')=0 AND instr(path,'#')=0),response_hash TEXT NOT NULL CHECK(length(response_hash)=66 AND substr(response_hash,1,2)='0x' AND substr(response_hash,3) NOT GLOB '*[^0-9a-f]*'),observed_at INTEGER NOT NULL CHECK(observed_at BETWEEN 946684800000 AND 4102444800000),metadata_bound INTEGER NOT NULL DEFAULT 0 CHECK(metadata_bound=0),PRIMARY KEY(verification_id,leaf_index)) STRICT;
CREATE INDEX IF NOT EXISTS idx_leaves_hash ON proof_leaves(leaf_hash);
CREATE TABLE IF NOT EXISTS rate_limits(key_id TEXT NOT NULL REFERENCES api_keys(key_id) ON DELETE CASCADE,window_start INTEGER NOT NULL CHECK(window_start>=0 AND window_start%60000=0),accepted_count INTEGER NOT NULL CHECK(accepted_count BETWEEN 1 AND 100),PRIMARY KEY(key_id,window_start)) STRICT,WITHOUT ROWID;CREATE INDEX IF NOT EXISTS idx_rate_limits_window ON rate_limits(window_start);
